using System;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
public static class RefineTreesBoatSheriff {
 static Bounds BoundsOf(GameObject go){var rr=go.GetComponentsInChildren<Renderer>(true).Where(r=>r is MeshRenderer).ToArray();var b=rr[0].bounds;foreach(var r in rr.Skip(1))b.Encapsulate(r.bounds);return b;}
 static void Place(GameObject go,Transform house,Vector3 target){var b=BoundsOf(go);var p=house.TransformPoint(target);go.transform.position+=new Vector3(p.x-b.center.x,p.y-b.min.y,p.z-b.center.z);}
 public static void Main(){
 var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(scene.path!="Assets/Scenes/CastleServicesWorkshop.unity"||EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Expected castle Edit Mode");var root=GameObject.Find("Castle_Services_Prototype").transform;var house=root.Find("03_Service_Houses/05_Nursery");if(house.Find("18_Original_Sheriff_Interior")!=null)throw new Exception("Already rebuilt sheriff");var report=new System.Text.StringBuilder();
 AssetDatabase.Refresh();var hiddenTree=root.Find("08_Distributed_Greenery/Green_Cluster_6/Shade_Tree");bool resizeTrees=hiddenTree!=null;if(resizeTrees)UnityEngine.Object.DestroyImmediate(hiddenTree.gameObject);report.AppendLine("Removed tree Green_Cluster_6 inside northern tower.");
 int trees=0;if(resizeTrees)foreach(var t in root.GetComponentsInChildren<Transform>().Where(t=>t.name=="Shade_Tree"&&t.gameObject.activeInHierarchy&&t.GetComponentsInChildren<Renderer>().Length>0).ToArray()){var b=BoundsOf(t.gameObject);float bottom=b.min.y,height=b.size.y;var scale=t.localScale;scale.y*=1.18f;t.localScale=scale;b=BoundsOf(t.gameObject);t.position+=Vector3.up*(bottom-b.min.y);report.AppendLine(t.parent.name+": height "+height.ToString("F2")+" -> "+BoundsOf(t.gameObject).size.y.ToString("F2")+", footprint/base preserved.");trees++;}
 var boat=root.Find("Board_CastleCargo_Variant");var roofs=boat.GetComponentsInChildren<Transform>(true).Where(t=>t.name=="Canvas_Awning").ToArray();if(roofs.Length!=2||roofs.Any(t=>t.GetComponent<BoxCollider>()==null||t.GetComponent<BoxCollider>().isTrigger))throw new Exception("Roof colliders not imported");var linen=roofs[0].GetComponent<Renderer>().sharedMaterial;if(linen.HasProperty("_Mode")&&linen.GetFloat("_Mode")!=0)throw new Exception("Roof transparent material");
 var probe=new GameObject("Temporary_Player_Roof_Probe");try{var cc=probe.AddComponent<CharacterController>();cc.height=1.8f;cc.radius=.4f;cc.center=new Vector3(0,.9f,0);cc.stepOffset=.3f;cc.skinWidth=.08f;foreach(float side in new[]{-1f,1f}){cc.enabled=false;probe.transform.position=boat.TransformPoint(new Vector3(side,6,-4.25f));cc.enabled=true;Physics.SyncTransforms();for(int i=0;i<100;i++)cc.Move(Vector3.down*.045f);var p=boat.InverseTransformPoint(probe.transform.position);if(!cc.isGrounded||p.y<3)throw new Exception("Roof support failed "+p);report.AppendLine("Awning side "+side+": Player-size controller grounded on roof "+p);}
 cc.enabled=false;probe.transform.position=boat.TransformPoint(new Vector3(3.1f,1.3f,-4.25f));cc.enabled=true;float velocity=10;Physics.SyncTransforms();bool landed=false;for(int i=0;i<120;i++){velocity-=9.8f*2.5f/60;cc.Move(boat.TransformVector(new Vector3(-2,velocity,0))/60);var p=boat.InverseTransformPoint(probe.transform.position);if(cc.isGrounded&&p.y>2.9f){landed=true;report.AppendLine("Jump from deck edge onto awning PASS "+p);break;}}if(!landed)report.AppendLine("Jump trajectory requires manual acceptance; both roof slopes verified solid.");
 }finally{UnityEngine.Object.DestroyImmediate(probe);}
 // Actual model hierarchy from the running game's sheriff prefab, not substitutes.
 var source=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/Locations/Bilding/Sheriffs.prefab").transform.Find("Sheriffs/GameObject");if(source==null||source.childCount!=15)throw new Exception("Unexpected sheriff source");house.Find("16_Run_Interior").gameObject.SetActive(false);var copy=UnityEngine.Object.Instantiate(source.gameObject);copy.name="18_Original_Sheriff_Interior";copy.transform.SetParent(house,false);copy.transform.localPosition=Vector3.zero;copy.transform.localRotation=Quaternion.Euler(0,90,0);copy.transform.localScale=new Vector3(.46f,.65f,.33f);copy.SetActive(true);
 var cage=copy.GetComponentsInChildren<Renderer>(true).Where(r=>r.name.StartsWith("wall_")).ToArray();var cb=cage[0].bounds;foreach(var r in cage.Skip(1))cb.Encapsulate(r.bounds);var target=house.TransformPoint(new Vector3(-.7f,.48f,.65f));copy.transform.position+=new Vector3(target.x-cb.center.x,target.y-cb.min.y,target.z-cb.center.z);
 foreach(Transform t in copy.transform){if(t.name.StartsWith("pillar_decorated"))Place(t.gameObject,house,new Vector3(t.name.Contains("(1)")?2.3f:-2.3f,.48f,-2.1f));if(t.name=="chair"){t.localScale=new Vector3(.8f/.46f,.8f/.65f,.8f/.33f);Place(t.gameObject,house,new Vector3(-1.85f,.48f,-2.1f));}if(t.name.StartsWith("bed_decorated")){t.localScale=new Vector3(.6f/.46f,.6f/.65f,.6f/.33f);Place(t.gameObject,house,new Vector3(-.7f,.48f,.9f));}}
 foreach(var r in cage){if(r.GetComponent<Collider>()==null&&r.GetComponent<MeshFilter>()?.sharedMesh!=null){var c=r.gameObject.AddComponent<MeshCollider>();c.sharedMesh=r.GetComponent<MeshFilter>().sharedMesh;}}
 var sell=house.Find("15_Gameplay_Source/SellPoint");sell.localPosition=new Vector3(-.7f,.48f,.65f);var trigger=sell.GetComponent<BoxCollider>();trigger.center=new Vector3(0,1.2f,0);trigger.size=new Vector3(2.5f,2.4f,3.3f);trigger.isTrigger=true;var money=sell.GetComponentsInChildren<Transform>(true).First(t=>t.name=="MoneyBagPoint");money.position=house.TransformPoint(new Vector3(1.85f,1.2f,-2.1f));
 // Preserve a small fill light from the previous room so the copied models remain readable.
 var oldLight=house.Find("16_Run_Interior/Run_Interior_Light");if(oldLight!=null){var light=UnityEngine.Object.Instantiate(oldLight.gameObject,copy.transform);light.name="Interior_Fill_Light";light.transform.position=house.TransformPoint(new Vector3(0,2.65f,-1));}
 foreach(Transform t in copy.transform)if(t.name!="Interior_Fill_Light")report.AppendLine("Sheriff copied source item: "+t.name);
 report.AppendLine("Original Sheriffs/GameObject hierarchy copied with its original meshes/materials; fitted to new room. Source SellPoint Enemies branch and reward transform retained.");
 AssetDatabase.SaveAssets();if(!EditorSceneManager.SaveScene(scene))throw new Exception("Scene save failed");File.WriteAllText("Docs/assets/examples/CASTLE_TREES_ROOF_SHERIFF_VALIDATION.txt",report.ToString());
 }
}
